"""Memory identity value objects.

记忆身份与时间范围等值对象。
"""

from __future__ import annotations

import base64
import json
from datetime import datetime, timezone
from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field, model_validator


def encode_redis_component(value: str | None) -> str:
    if value is None:
        return "_"
    encoded = base64.urlsafe_b64encode(value.encode("utf-8")).decode("ascii")
    return "v" + encoded.rstrip("=")


class MemoryNamespace(BaseModel):
    """Immutable canonical storage partition generated by Mems."""

    model_config = ConfigDict(frozen=True)

    segments: tuple[str | None, ...]

    @classmethod
    def build(
        cls,
        *,
        tenant_id: str | None,
        user_id: str | None,
        agent_id: str,
        path: tuple[str, ...] = (),
    ) -> "MemoryNamespace":
        return cls(
            segments=(
                "v1",
                "tenant",
                tenant_id,
                "user",
                user_id,
                "agent",
                agent_id,
                "memories",
                *path,
            )
        )

    @classmethod
    def from_key(cls, key: str) -> "MemoryNamespace":
        return cls(segments=tuple(json.loads(key)))

    @property
    def key(self) -> str:
        """Serialize segments without delimiter ambiguity."""
        return json.dumps(self.segments, ensure_ascii=False, separators=(",", ":"))


class MemoryIdentity(BaseModel):
    """Immutable memory identity used for isolation and key generation.

    不可变的记忆身份值对象，用于隔离过滤与存储键构造。
    """

    model_config = ConfigDict(frozen=True)

    tenant_id: Optional[str] = None
    user_id: Optional[str] = None
    agent_id: str
    session_id: Optional[str] = None
    namespace_segments: tuple[str, ...] = Field(default_factory=tuple, exclude=True)
    memory_namespace: Optional[MemoryNamespace] = Field(default=None, exclude=True)

    @model_validator(mode="after")
    def generate_namespace(self) -> "MemoryIdentity":
        if self.memory_namespace is None:
            object.__setattr__(
                self,
                "memory_namespace",
                MemoryNamespace.build(
                    tenant_id=self.tenant_id,
                    user_id=self.user_id,
                    agent_id=self.agent_id,
                    path=self.namespace_segments,
                ),
            )
        return self

    @property
    def namespace_key(self) -> str:
        assert self.memory_namespace is not None
        return self.memory_namespace.key

    def redis_key(self) -> str:
        """Build the stable L0 Redis key from identity fields.

        根据身份字段构造稳定的 L0 Redis 键。
        """
        return ":".join(
            (
                "mems",
                "l0",
                encode_redis_component(self.tenant_id),
                encode_redis_component(self.user_id),
                encode_redis_component(self.namespace_key),
                encode_redis_component(self.agent_id),
                encode_redis_component(self.session_id),
            )
        )

    def filter_fields(self) -> dict[str, Any]:
        """Return non-None tenant/user/namespace fields for SQL/Qdrant filtering.

        返回用于 SQL/Qdrant 过滤的非空身份字段。
        """
        fields: dict[str, Any] = {}
        if self.tenant_id is not None:
            fields["tenant_id"] = self.tenant_id
        if self.user_id is not None:
            fields["user_id"] = self.user_id
        fields["namespace"] = self.namespace_key
        return fields

    def as_dict(self) -> dict[str, Any]:
        """Return all identity fields as a plain dictionary."""
        return {
            "tenant_id": self.tenant_id,
            "user_id": self.user_id,
            "agent_id": self.agent_id,
            "session_id": self.session_id,
            "namespace": self.namespace_key,
        }


class TimeRange(BaseModel):
    """An optional half-open time range used by re-distillation filters.

    再蒸馏过滤使用的可选时间范围值对象。
    """

    model_config = ConfigDict(frozen=True)

    start: Optional[datetime] = None
    end: Optional[datetime] = None

    @staticmethod
    def _as_utc(value: datetime) -> datetime:
        if value.tzinfo is None:
            return value.replace(tzinfo=timezone.utc)
        return value

    def contains(self, value: datetime) -> bool:
        """Return True when ``value`` falls inside the configured range."""
        value = self._as_utc(value)
        if self.start is not None and value < self._as_utc(self.start):
            return False
        if self.end is not None and value > self._as_utc(self.end):
            return False
        return True


class Importance(BaseModel):
    """Bounded importance value used by distillation policy decisions.

    用于蒸馏策略判断的有界重要度值对象。
    """

    model_config = ConfigDict(frozen=True)

    value: float = Field(ge=0.0, le=1.0)

    def is_high_value(self, threshold: float) -> bool:
        return self.value >= threshold

    def as_float(self) -> float:
        return self.value
